import { db } from '../firebase/config';
import { collection, setDoc, getDoc, getDocs, updateDoc, deleteDoc, doc, query, where, serverTimestamp } from 'firebase/firestore';
import type { Feedback } from '../types/Feedback';

// Collection: feedback. Document IDs are generated by Firestore and copied into fbID.
const COLLECTION = 'feedback';

// ~~~~~~~~~~ CREATE ~~~~~~~~~~

// Returns the new fbID. A session should only ever be rated once: enforce that in the rules / a Cloud Function.
export const createFeedback = async (data: Omit<Feedback, 'fbID' | 'fbTimestamp'>): Promise<string> => {
  try {
    const ref = doc(collection(db, COLLECTION));
    await setDoc(ref, { ...data, fbID: ref.id, fbTimestamp: serverTimestamp() });
    return ref.id;
  } catch (error) {
    console.error('Error creating feedback:', error);
    throw error;
  }
};

// ~~~~~~~~~~ READ ~~~~~~~~~~

// Get feedback by fbID
export const getFeedback = async (fbID: string): Promise<Feedback | null> => {
  try {
    const snap = await getDoc(doc(db, COLLECTION, fbID));
    return snap.exists() ? (snap.data() as Feedback) : null;
  } catch (error) {
    console.error(`Error getting feedback "${fbID}":`, error);
    throw error;
  }
};

// Get the feedback left for a session (null if it hasn't been rated yet)
export const getFeedbackBySession = async (sessID: string): Promise<Feedback | null> => {
  try {
    const snap = await getDocs(query(collection(db, COLLECTION), where('sessID', '==', sessID)));
    return snap.empty ? null : (snap.docs[0].data() as Feedback);
  } catch (error) {
    console.error(`Error getting feedback for session "${sessID}":`, error);
    throw error;
  }
};

// ~~~~~~~~~~ UPDATE ~~~~~~~~~~

export const updateFeedback = async (fbID: string, updates: Partial<Omit<Feedback, 'fbID'>>): Promise<void> => {
  try {
    await updateDoc(doc(db, COLLECTION, fbID), { ...updates });
  } catch (error) {
    console.error(`Error updating feedback "${fbID}":`, error);
    throw error;
  }
};

// ~~~~~~~~~~ DELETE ~~~~~~~~~~

export const deleteFeedback = async (fbID: string): Promise<void> => {
  try {
    await deleteDoc(doc(db, COLLECTION, fbID));
  } catch (error) {
    console.error(`Error deleting feedback "${fbID}":`, error);
    throw error;
  }
};